params.source:
component Treasury { gold: 1000 }
component Morale { level: 50 }
let plan = sandbox_input()
let k = get_entity("kingdom")
let t = get(k, Treasury) |> unwrap
let m = get(k, Morale) |> unwrap
set(k, Treasury { gold: t.gold - plan["spend"] })
set(k, Morale { level: m.level + plan["gain"] })
sandbox_output({ "new_gold": t.gold - plan["spend"], "new_morale": m.level + plan["gain"] })
